INSERT INTO @meta (OrgId,Website,ProfileNote) VALUES
(20962, NULL, N'BC-based real estate developer and general contractor with offices in Vancouver (300-911 Homer St) and North Vancouver (25 Wallace Mews). Holds active BC Developer licence #45520 and GC licence #45122. No public-facing company website located.'),
(18992, N'https://reotech.ca', N'Coquitlam BC commercial interior construction specialist founded 1989; 51-200 employees. Delivers tenant improvements, construction management, and general contracting for office, healthcare, education, and hospitality clients across Metro Vancouver.'),
(20586, N'https://medcorp.ca', N'Surrey BC general contractor founded 2016 specializing in customized workspace buildouts for medical and dental professionals throughout the Lower Mainland. BBB A+ rating; six completed dental/medical clinic projects across Abbotsford, Coquitlam, Surrey, Maple Ridge, and Chilliwack.'),
(33440, N'https://www.oksfeldtdevelopments.com', N'North Vancouver boutique custom home builder and GC; family business tracing to 1953 Danish-immigrant founder Oksfeldt Molby. Holds BC General Contractor licence #53080. Focuses on select custom homes, renovations, and construction management in the Lower Mainland.'),
(10119, N'https://www.kdsconstruction.ca', N'Surrey BC general contractor and construction manager established 1984. Serves healthcare, institutional, commercial, food manufacturing, and light industrial sectors across Metro Vancouver and the Fraser Valley. 51-200 employees.'),
(55, N'https://www.vintop.ca', N'New Westminster BC developer and construction/marketing firm operating 30+ years; one-stop platform covering development management, construction, and sales. Notable for a BC Housing public-private partnership (66-unit PAL New West affordable rental, 2024) and the Ovation mid-rise in New Westminster.'),
(28005, N'https://www.cmpgroups.com', N'Vancouver-based vertically integrated general contractor and developer founded 2005; specializes in multi-family wood-frame apartments, townhomes, and commercial tenant improvement. Head office 408-2052 West 41st Ave, Vancouver. Combines construction management, development, and real estate finance.'),
(71980, N'https://www.metalbuildinggroup.ca', N'Surrey BC steel and metal building contractor (head office 303-15240 56th Ave, Surrey V3S 5K7) with 30+ years operating in Western Canada. Specializes in design-build pre-engineered metal buildings for industrial, commercial, agricultural, and recreational clients across BC and Alberta.'),
(36067, N'https://www.qualitech604.com', N'Family-owned Lower Mainland general contractor founded 2003; specializes in residential construction management, custom homes, and commercial tenant improvements. HPO-licensed; 2016 Georgie Awards finalist; 1,700+ units completed across Greater Vancouver.'),
(104, N'https://sakuradevelopments.com', N'Victoria BC real estate developer active since 1996; delivers multi-family condominiums, mixed-use, commercial, and custom single-family projects, managing land acquisition through sales. Distinct from the Vancouver-based Sakura Project Management entity.'),
(26285, N'https://www.boasconstruction.com', N'Port Coquitlam BC design-build contractor founded 2011; specializes in residential renovations, custom homes, commercial tenant improvements, and millwork. Small Korean-owned firm operating across Metro Vancouver. Distinct from Bosa Construction.'),
(20061, N'https://cressey.com', N'Established 1969 Vancouver real estate developer with a 57-year track record; delivers condominium, rental, and mixed-use projects across Metro Vancouver, Whistler, Alberta, and Washington State. Approximately 162 employees.'),
(11188, N'https://www.m3dm.ca/', N'Calgary-headquartered development management firm (est. 2016) with active BC offices in Vancouver (#330-34 W 7th Ave) and Victoria. Provides owner-rep, project management, cost management, and development management services for complex projects across Canada; BC work includes Senakw (1M sq ft, Vancouver, owner-rep for OPTrust).'),
(20176, N'https://www.pathgc.com/', N'Commercial general contractor based in Langley BC (8840 210th St, Langley BC V1M 2Y2), incorporated 2015. Specializes in commercial renovations including office, retail, restaurant, and base-building work across Metro Vancouver. A+ BBB rating. Provides design-build, design-assist, fixed-price, and construction management services.'),
(20607, N'https://www.seasonscontractingltd.com/', N'Commercial contractor based in Abbotsford BC (302A-33771 George Ferguson Way, V2S 2M5) specializing in dental and medical clinic construction and renovation across Metro Vancouver and Fraser Valley. 15+ years in business, 200+ completed projects. Turnkey service including interior design.'),
(148, NULL, N'BC-incorporated property holding company (incorporated 2007-09-25, LEI 549300R7S6DSL98VUR26) registered at 400-1245 West Broadway, Vancouver BC V6H 1G7. Owns the Delta Shoppers Mall site at 8037-8087 120 Street, North Delta (6-acre strip mall built 2004). Site approved Feb 2024 for 876-home mixed-use redevelopment by Value Property Group.'),
(210, N'https://www.alvairgroup.com/', N'Surrey BC residential developer (168-12830 96 Ave, Surrey BC V3V 0C2) with 25+ years building residential communities across BC. Develops single-family homes and multi-family residential projects in the Lower Mainland. Also operates as Alvair Development Ltd.'),
(37, N'http://armanihomes.ca/', N'Custom home builder and developer based in Port Moody BC (2 Greystone Place, Port Moody BC), serving the Tri-Cities area of Metro Vancouver. CHBA and HAVAN member. Builds custom single-family homes with personalized design via Choice Plans; partners with local sub-trades and land developers to create communities.'),
(176, N'https://axommconstruction.ca/', N'Vancouver-based general contractor and construction project manager with 20+ years of experience and 35+ delivered projects. Specializes in 5-storey mixed-use residential/commercial buildings, residential row houses, luxury residential, and tenant improvements across BC. Works with qualified trades and sub-contractors to reduce project costs.'),
(75124, N'https://bridgemarkdevelopment.com/', N'Vancouver-based real estate developer and consulting firm (#309-63 West 6th Ave, Vancouver BC V5Y 1K2; also cited at 998 Harbourside Dr, North Vancouver) with 35+ years of combined team experience and $3B+ in managed real estate. Active development pipeline in Surrey and Langley including high-rise towers; completed portfolio in Surrey, Coquitlam, Burnaby, and Vancouver. Also p'),
(35, N'https://corsadevelopments.com/', N'BC residential developer (604-537-7778) focused on building single-family homes, townhomes, and condos in the Lower Mainland. Tagline: ''Redefining the Urban Community.'' Online presence is limited and no leadership names are publicly listed. Distinct from Corsa Development Group (Post Falls, Idaho, USA).'),
(6947, N'https://enduroconstruction.ca', N'Vancouver-based full-service general contractor and construction management firm (office at #170-422 Richards St, Vancouver BC) operating across the Lower Mainland and Sea-to-Sky corridor. Specializes in commercial renovations, tenant improvements, institutional fit-outs and residential builds; clients include UBC and BC government. General inbox info@enduroconstruction.ca, ph '),
(213, NULL, N'BC private real estate development company registered as Gibbins Road Holdings Inc., active in the Cowichan Valley (Duncan / North Cowichan, Vancouver Island). Received unanimous council approval May 2024 for a 100-unit, 4-storey mixed-use rental building at 3096 Gibbins Rd, near Cowichan District Hospital.'),
(71895, N'https://gibraltar.ca', N'Gibraltar Holdings Ltd. (dba Gibraltar Construction) is a BC commercial general contractor founded 1993, HQ at 520 Sharpe St, New Westminster BC. Specializes in tenant improvements, dental/medical offices, financial institutions and commercial renovations across BC with 9,000+ completed projects. Ph (604) 874-9292.'),
(126, N'https://www.kyodaiproperties.com', N'Vancouver-based property management and real estate investment company; registered office Kyodai Holdings Ltd at 51 E Pender St, Vancouver BC. Manages a commercial and residential tenant portfolio; site references the Rennie organization. General inbox info@kyodaiproperties.com; no named staff published.'),
(118, N'https://www.moodyparkhomes.ca', N'Moody Park Homes Ltd is a Surrey-based BC home builder (est. 2013) focused on Lower Mainland residential development. The ''Edmonds J.V.'' suffix is a joint-venture designation; no separate public registration or JV partner surfaced. Phone 604-649-9793.'),
(206, N'https://www.plant-builders.com', N'BC-based general contractor / builder with a portfolio including a residential mixed-use development in Langford, BC. The ''plant-based'' branding likely refers to wood/sustainable construction. Website is live but most subpages return 404 as of June 2026; general inbox info@plant-builders.com. No named personnel found publicly.'),
(34554, N'https://www.prosperoussquare.com', N'Richmond, BC-based custom home builder and general contractor (est. 2014, Chinese-Canadian ownership). Serves residential and commercial renovation markets in greater Vancouver. Small firm (2-10 employees); BC contractor licences #53443 and #40455 now cancelled/inactive. General email prosperoussquare@gmail.com.'),
(120, NULL, N'BC-incorporated land developer; registered office Suite 509-1755 West Broadway, Vancouver. Beneficial owners are Karen Wai Har Woo, Edwin Ying Yuen Lee and Joanne Fay Kit Gunn. Active rezoning for a 26-storey, 208-unit purpose-built rental tower at 1668 West Broadway, Fairview (W.T. Leung Architects).'),
(5, N'https://willowtreehomes.ca', N'Surrey, BC-based land developer and homebuilder founded 2004 (Willow Tree Homes Ltd; office Unit 211-15292 Croydon Dr, Surrey BC). Builds eco-conscious residential communities (townhomes, condos, single-family) across Metro Vancouver, Fraser Valley and Chilliwack. General inbox info@willowtreehomes.ca.');
